<script lang="ts">
 import type {Snippet} from 'svelte';
 import {onMount} from 'svelte';
 import {page} from '$app/state';
 import '$lib/components/ui/tokens.css';
 import SceneBanner, {type Banner} from './SceneBanner.svelte';
 let {children,tools=false,siteName='个人综合站',intro='记录想法、分享作品，收藏日常。',banner=null}:{children:Snippet;tools?:boolean;siteName?:string;intro?:string;banner?:Banner|null}=$props();
 let theme=$state('system');let menuOpen=$state(false);let scrollY=$state(0);let settingsOpen=$state(false);let backdrop=$state(true);let reducedMotion=$state(false);
 const home=$derived(page.url.pathname==='/');
 const showScene=$derived(home && backdrop);
 function setBackdrop(value:boolean){backdrop=value;try{localStorage.setItem('scene-background',String(value));}catch{/* optional */}}
 const links=[['/articles','文章'],['/notes','笔记'],['/moments','动态'],['/projects','作品']];
 const activePath=$derived(page.url.pathname);
 const isActive=(href:string)=>activePath===href||activePath.startsWith(`${href}/`);
 function setTheme(value:string){theme=value;document.documentElement.dataset.theme=value;try{localStorage.setItem('theme',value);}catch{/* optional */}}
 function setMotion(value:boolean){reducedMotion=value;document.documentElement.dataset.motion=value?'reduced':'full';try{localStorage.setItem('motion',value?'reduced':'full');}catch{/* optional */}}
 onMount(()=>{try{const value=localStorage.getItem('theme');if(value&&['light','dark','system'].includes(value))setTheme(value);const savedBackdrop=localStorage.getItem('scene-background');if(savedBackdrop!==null)backdrop=savedBackdrop!=='false';const motion=localStorage.getItem('motion');if(motion==='reduced')setMotion(true);}catch{/* optional */}});
</script>
<svelte:window bind:scrollY />
<svelte:head><meta name="color-scheme" content="light dark" /></svelte:head>
<a class="skip" href="#public-main">跳到主要内容</a>
<header class="site-header" class:home-header={showScene} class:over-scene={showScene && scrollY<320 && !menuOpen}>
 <div class="nav-inner">
  <a class="brand-profile" href="/" aria-label={`${siteName}首页`}><img src="/images/makeine-anna.png" alt="八奈见杏菜头像" width="34" height="34" /><span class="brand-profile-copy"><strong>{siteName}</strong><small>记录、创作与小小日常</small></span></a>
  <nav class="desktop-nav" aria-label="主要导航">{#each links as [href,label]}<a {href} class:active={isActive(href)} aria-current={isActive(href)?'page':undefined}>{label}</a>{/each}{#if tools}<a href="/tools" class:active={isActive('/tools')} aria-current={isActive('/tools')?'page':undefined}>工具</a>{/if}<a href="/search" class:active={isActive('/search')} aria-current={isActive('/search')?'page':undefined}>⌕ 搜索</a><details><summary>更多</summary><div class="menu"><a href="/resources">资源</a><a href="/tags">标签</a><a href="/series">系列</a><a href="/about">关于</a></div></details></nav>
  <div class="header-actions"><button class="settings-trigger" type="button" aria-expanded={settingsOpen} onclick={()=>settingsOpen=!settingsOpen}>☼ <span>显示</span></button><label class="theme"><span class="sr-only">主题</span><select aria-label="主题" value={theme} onchange={e=>setTheme(e.currentTarget.value)}><option value="system">系统</option><option value="light">浅色</option><option value="dark">深色</option></select></label><button class="menu-toggle" type="button" aria-expanded={menuOpen} aria-controls="mobile-menu" onclick={()=>menuOpen=!menuOpen}>{menuOpen?'关闭':'菜单'}</button></div>
 </div>
 {#if settingsOpen}<div class="settings-popover"><div><strong>显示设置</strong><button class="close-settings" type="button" onclick={()=>settingsOpen=false} aria-label="关闭显示设置">×</button></div><label class="setting-row"><span>场景背景</span><input type="checkbox" checked={backdrop} onchange={e=>setBackdrop(e.currentTarget.checked)} /></label><label class="setting-row"><span>减少动效</span><input type="checkbox" checked={reducedMotion} onchange={e=>setMotion(e.currentTarget.checked)} /></label><small>场景背景控制首页大图与全站纹理；减少动效勾选后停止动画。设置保存在本机。</small></div>{/if}
 {#if menuOpen}<nav id="mobile-menu" class="mobile-menu" aria-label="移动端导航">{#each links as [href,label]}<a {href} class:active={isActive(href)} onclick={()=>menuOpen=false}>{label}</a>{/each}{#if tools}<a href="/tools">工具</a>{/if}<a href="/search">搜索</a><a href="/resources">资源</a><a href="/tags">标签</a><a href="/series">系列</a><a href="/about">关于</a></nav>{/if}
</header>
{#if showScene}<SceneBanner {siteName} {banner} />{/if}
<div class="public-shell" class:home-shell={showScene} class:plain-background={!backdrop} id="public-main">
 <aside class="space-sidebar" aria-label="个人空间">
  <a class="profile-art" href="/about"><img src="/images/makeine-img_visual03.jpg" alt="八奈见杏菜" width="260" height="220" /></a>
  <div class="profile-copy"><div class="profile-kicker">PERSONAL SPACE</div><h2>{siteName}</h2><p>{intro}</p><div class="profile-links"><a href="/about">关于这里 ↗</a><a href="/rss.xml">RSS ↗</a></div></div>
  <nav class="section-nav" aria-label="空间栏目"><h3>在这里逛逛</h3>{#each [...links,['/tools','工具'],['/resources','资源'],['/tags','标签'],['/series','系列']] as [href,label]}<a {href} class:active={isActive(href)}><span>{label}</span><span aria-hidden="true">↗</span></a>{/each}</nav>
 </aside>
 <div class="content-column">{@render children()}</div>
 <aside class="utility-sidebar" aria-label="站点工具">
  <section class="utility-block"><p class="utility-kicker">STATS</p><a href="/articles"><span>文章</span><b>记录</b></a><a href="/moments"><span>动态</span><b>日常</b></a><a href="/projects"><span>作品</span><b>创作</b></a><a href="/tags"><span>标签</span><b>探索</b></a></section>
  <section class="utility-block"><p class="utility-kicker">NOW BROWSING</p><strong>{home?'首页':'站点栏目'}</strong><p class="utility-copy">慢慢浏览，随手记下值得回看的东西。</p></section><section class="utility-block"><p class="utility-kicker">QUICK LINKS</p><a href="/updates">最近更新 <span>↗</span></a><a href="/search">站内搜索 <span>⌕</span></a><a href="/rss.xml">订阅 RSS <span>↗</span></a></section>
  <section class="utility-block utility-status"><p class="utility-kicker">SITE STATUS</p><div><span class="status-dot"></span><span>在线记录中</span></div><small>最后更新 · {new Date().toLocaleDateString('zh-CN')}</small></section>
  <button class="utility-settings" type="button" onclick={()=>settingsOpen=!settingsOpen}>☼ 显示设置</button>
 </aside>
</div>
<footer><div class="footer-inner"><p class="footer-signature">把好奇心写成记录，把过程留给以后。</p><nav aria-label="页脚导航"><a href="/articles">文章</a><a href="/notes">笔记</a><a href="/projects">作品</a><a href="/about">关于</a><a href="/rss.xml">RSS</a></nav><p class="muted">© {new Date().getFullYear()} {siteName}</p></div></footer>
<style>
:global(body:has(.public-shell)){background-color:var(--canvas);background-image:radial-gradient(color-mix(in srgb,var(--primary) 8%,transparent) 1px,transparent 1px);background-size:18px 18px}
:global(body:has(.public-shell.plain-background)){background-image:none}
.site-header{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--surface) 94%,transparent);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.site-header.home-header{position:fixed;inset:0 0 auto;background:transparent;border-bottom-color:transparent;box-shadow:none}.site-header.home-header:not(.over-scene){background:color-mix(in srgb,var(--surface) 94%,transparent);border-bottom-color:var(--line);box-shadow:0 6px 24px #1d24420d}.site-header.over-scene{background:transparent;border-bottom-color:transparent;color:white;box-shadow:none}.nav-inner{max-width:1400px;min-height:64px;margin:auto;padding:7px 22px;display:flex;align-items:center;gap:22px}.brand-profile{display:flex;align-items:center;gap:10px;text-decoration:none;color:inherit;min-width:0}.brand-profile img{width:34px;height:34px;border-radius:50%;flex-shrink:0}.brand-profile-copy{display:grid;line-height:1.3;gap:2px}.brand-profile-copy strong{font-size:14px}.brand-profile-copy small{font-size:10px;color:var(--muted)}.over-scene .brand-profile-copy small{color:#e8eff6}.desktop-nav{display:flex;align-items:center;gap:2px}.desktop-nav a,.desktop-nav summary{display:inline-flex;align-items:center;min-height:40px;padding:6px 11px;border-radius:4px;color:inherit;text-decoration:none;font-size:13px}.desktop-nav a:hover,.desktop-nav summary:hover,.desktop-nav a.active{background:transparent;color:var(--primary);text-shadow:none;border-bottom:2px solid currentColor}.over-scene .desktop-nav a:hover,.over-scene .desktop-nav a.active{background:transparent;color:#fff;border-bottom-color:#fff}.desktop-nav details{position:relative}.menu{position:absolute;right:0;top:44px;z-index:30;display:grid;min-width:132px;padding:7px;background:var(--surface);color:var(--text);text-shadow:none;border:1px solid var(--line);border-radius:11px;box-shadow:var(--shadow-sm)}.menu a{color:var(--text)!important}.header-actions{margin-left:auto;display:flex;align-items:center;gap:7px}.theme{margin:0}.theme select{width:auto;min-height:36px;padding:4px 8px;background:var(--surface);color:var(--text);font-size:12px}.over-scene .theme select{background:#17283b85;color:#fff;border-color:#ffffff55}.over-scene .menu-toggle{background:transparent;color:#fff;border-color:#ffffff55}.theme option{background:var(--surface);color:var(--text)}.settings-trigger,.utility-settings{min-height:36px;padding:5px 10px;border:1px solid var(--line);border-radius:9px;background:transparent;font-size:12px}.over-scene .settings-trigger{color:#fff;border-color:#ffffff55}.settings-popover{position:absolute;right:22px;top:66px;width:230px;padding:15px;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:13px;box-shadow:0 18px 48px #14223926}.settings-popover>div{display:flex;align-items:center;justify-content:space-between;margin-bottom:9px}.settings-popover strong{font-size:13px}.close-settings{border:0;background:none;min-height:28px;padding:2px 6px}.setting-row{display:flex;align-items:center;justify-content:space-between;min-height:38px;margin:0;border-top:1px solid var(--line);font-size:12px}.setting-row input{width:18px;min-height:18px}.settings-popover small{display:block;font-size:10px;line-height:1.6;margin-top:8px}.menu-toggle{display:none}.mobile-menu{display:none}
.public-shell{max-width:1440px;margin:auto;padding:28px 22px 56px;display:grid;grid-template-columns:258px minmax(0,1fr) 246px;gap:18px;align-items:start;min-height:75vh}.home-shell{position:relative;margin-top:-32px;padding-top:0;z-index:4}.space-sidebar,.utility-sidebar{background:color-mix(in srgb,var(--surface) 92%,transparent);border:1px solid var(--line);border-radius:14px;overflow:hidden;position:sticky;top:92px;min-width:0}.profile-art{display:block;margin:10px 10px 0;overflow:hidden;border-radius:9px}.profile-art img{display:block;width:100%;height:205px;object-fit:cover;object-position:center 22%}.profile-copy{padding:16px 18px 13px}.profile-kicker,.utility-kicker{font:10px/1.4 'DM Mono',monospace;letter-spacing:.12em;color:var(--primary);margin:0 0 6px}.profile-copy h2{font-size:19px;margin:0 0 7px}.profile-copy p{font-size:12px;color:var(--muted);line-height:1.75;margin-bottom:9px}.profile-links{display:flex;gap:14px}.profile-links a{display:inline-flex;align-items:center;min-height:34px;font-size:12px;text-decoration:none}.section-nav{padding:8px 13px 15px;border-top:1px solid var(--line)}.section-nav h3{font-size:11px;color:var(--muted);margin:10px 8px 5px}.section-nav>a{display:flex;justify-content:space-between;align-items:center;min-height:36px;padding:5px 9px;text-decoration:none;color:var(--text);border-radius:7px;font-size:13px}.section-nav>a.active,.section-nav>a:hover{background:var(--soft);color:var(--primary)}.content-column{min-width:0}.utility-sidebar{padding:14px 15px}.utility-block{padding:5px 0 16px;margin-bottom:14px;border-bottom:1px solid var(--line)}.utility-block:last-of-type{margin-bottom:0}.utility-block strong{display:block;font-size:17px;margin:3px 0 6px}.utility-copy{font-size:12px;color:var(--muted);line-height:1.7;margin:0}.utility-block>a{display:flex;justify-content:space-between;align-items:center;gap:12px;min-height:34px;padding:3px 0;color:var(--text);font-size:12px;text-decoration:none;border-bottom:1px dotted var(--border)}.utility-block>a b{font-weight:500;color:var(--muted)}.utility-block>a:hover{color:var(--primary)}.utility-block>a span{color:var(--muted)}.utility-status>div{display:flex;align-items:center;gap:7px;font-size:12px}.status-dot{width:7px;height:7px;border-radius:50%;background:#76b58a;box-shadow:0 0 0 3px #76b58a1f}.utility-status small{display:block;color:var(--muted);font-size:10px;margin-top:7px}.utility-settings{width:100%;margin-top:2px;color:var(--muted)}.utility-settings:hover{color:var(--primary);border-color:var(--primary)}footer{border-top:1px solid var(--line)}.footer-inner{max-width:1440px;margin:auto;padding:24px;display:flex;justify-content:space-between;gap:24px;align-items:center;font-size:12px;color:var(--muted)}.footer-inner p{margin:0}.footer-inner nav{display:flex;flex-wrap:wrap;gap:16px}.footer-inner a{text-decoration:none;color:inherit}.skip{position:fixed;left:16px;top:12px;transform:translateY(-200%);padding:12px 16px;background:var(--surface);border-radius:9px;z-index:40}.skip:focus{transform:none}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}:global(.public-shell){overflow-wrap:anywhere;scroll-margin-top:84px}:global(.public-shell :focus-visible){scroll-margin-block:84px}
@media(max-width:1180px){.public-shell{grid-template-columns:224px minmax(0,1fr) 210px;gap:14px;padding-inline:16px}.nav-inner{gap:12px}.desktop-nav a,.desktop-nav summary{padding-inline:8px}.brand-profile-copy small{display:none}}
@media(max-width:950px){.utility-sidebar{display:none}.public-shell{grid-template-columns:210px minmax(0,1fr)}.settings-trigger span{display:none}}
@media(max-width:760px){.site-header,.site-header.home-header{top:8px;inset-inline:8px;margin:0;border-radius:13px}.desktop-nav{display:none}.menu-toggle{display:block}.mobile-menu{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:9px 12px;gap:5px;background:var(--surface);border-top:1px solid var(--line);border-radius:0 0 13px 13px}.mobile-menu a{padding:8px;text-decoration:none;color:var(--text);min-height:40px;font-size:13px}.mobile-menu a.active{background:var(--soft)}.nav-inner{padding-inline:10px}.public-shell{display:block;padding:18px 13px 36px}.home-shell{padding-top:0;margin-top:-13px}.space-sidebar{display:none}.brand-profile-copy strong{font-size:13px}.settings-popover{right:10px;top:58px}.footer-inner{flex-wrap:wrap;padding:22px 16px;gap:12px}.footer-signature{width:100%}}
</style>
